package br.com.marquesautodetail.api.security; import br.com.marquesautodetail.api.usuario.UsuarioRepository; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service;
@Service public class CustomUserDetailsService implements UserDetailsService{ private final UsuarioRepository repo; public CustomUserDetailsService(UsuarioRepository repo){this.repo=repo;} public UserDetails loadUserByUsername(String email){var u=repo.findByEmail(email).orElseThrow(()->new UsernameNotFoundException("Usuário não encontrado")); return User.withUsername(u.getEmail()).password(u.getSenha()).roles(u.getRole().name()).disabled(!Boolean.TRUE.equals(u.getAtivo())).build();}}
